[Form]
public class AVAChangeWorkPriority extends FormRun
{
    FormDataSource formDataSource;
    WHSWorkTable whsWorktable;

}

/// <summary>
/// init
/// </summary>
public void init()
{
    AVAOverviewAllWorkPositionsView AVAOverviewAllWorkPositionsView;
    AVAOverviewAllLoadWorkCreatedDetailView AVAOverviewAllLoadWorkCreatedDetailView;
    FormRun callingForm;
    Common  callingRecord = element.args().record();

    super();

    if (FormDataUtil::isFormDataSource(callingRecord))
    {
        callingForm = element.args().caller();

        FormTabPageControl OverviewAllWorkPositionsTabPage = callingForm.design().controlName(formControlStr(AVAWHSWorkOverview, OverviewAllWorkPositionsTabPage));
        FormTabPageControl OverviewAllLoadWorkCreatedTabPage = callingForm.design().controlName(formControlStr(AVAWHSWorkOverview, OverviewAllLoadWorkCreatedTabPage));
        if (OverviewAllWorkPositionsTabPage.isActivePage())
        {
            formDataSource = callingForm.dataSource(FormDataSourceSTr(AVAWHSWorkOverview,AVAOverviewAllWorkPositionsView));
            AVAOverviewAllWorkPositionsView = formDataSource.cursor();
            WHSWorkPriority.value(AVAOverviewAllWorkPositionsView.WorkPriority);
            whsWorktable = whsWorktable::find(AVAOverviewAllWorkPositionsView.WorkId, true);
        }
        else if (OverviewAllLoadWorkCreatedTabPage.isActivePage())
        {
            formDataSource = callingForm.dataSource(FormDataSourceSTr(AVAWHSWorkOverview,AVAOverviewAllLoadWorkCreatedDetailView));
            AVAOverviewAllLoadWorkCreatedDetailView = formDataSource.cursor();
            WHSWorkPriority.value(AVAOverviewAllLoadWorkCreatedDetailView.WorkPriority);
            whsWorktable = whsWorktable::find(AVAOverviewAllLoadWorkCreatedDetailView.WorkId, true);
        }
    }
}

/// <summary>
/// closeOk
/// </summary>
public void closeOk()
{
    whsWorktable whsWorktableloc;

    super();

    while select WorkPriority from whsWorktableloc
        where whsWorktableloc.WorkId == whsWorktable.WorkId
    {
        ttsbegin;
        whsWorktableloc.selectForUpdate(true);
        whsWorktableloc.WorkPriority = WHSWorkPriority.value();
        whsWorktableloc.doUpdate();
        ttscommit;
    }

    formDataSource.reread();
    formDataSource.refresh();

    // A call to active() is needed to trigger the button state update logic.
    formDataSource.active();       
}
